(() => {
  const sizeInput = document.getElementById('dl-size-input');
  const speedInput = document.getElementById('dl-speed-input');
  const overheadInput = document.getElementById('dl-overhead-input');
  const overheadVal = document.getElementById('dl-overhead-val');
  const capInput = document.getElementById('dl-cap-input');
  const resRealTime = document.getElementById('res-real-time');
  const resIdealTime = document.getElementById('res-ideal-time');
  const resTransferRate = document.getElementById('res-transfer-rate');
  const resCapCard = document.getElementById('res-cap-card');
  const resCapBar = document.getElementById('res-cap-bar');
  const resCapUsed = document.getElementById('res-cap-used');
  const resCapRemaining = document.getElementById('res-cap-remaining');

  function formatSeconds(sec) {
    if (!isFinite(sec) || sec <= 0) return '0s';
    const s = Math.floor(sec % 60);
    const m = Math.floor((sec / 60) % 60);
    const h = Math.floor((sec / 3600) % 24);
    const d = Math.floor(sec / 86400);
    const parts = [];
    if (d > 0) parts.push(d + 'd');
    if (h > 0) parts.push(h + 'h');
    if (m > 0) parts.push(m + 'm');
    if (s > 0 || parts.length === 0) parts.push(s + 's');
    return parts.join(' ');
  }

  function update() {
    const sizeGb = parseFloat(sizeInput.value) || 0;
    const speedMbps = parseFloat(speedInput.value) || 0;
    const overhead = parseFloat(overheadInput.value) || 0;
    const capGb = parseFloat(capInput.value) || 0;
    overheadVal.textContent = overhead + '%';

    if (sizeGb <= 0 || speedMbps <= 0) {
      resRealTime.textContent = '0s';
      resIdealTime.textContent = '0s';
      resTransferRate.textContent = '0 MB/s';
      return;
    }

    const totalMbits = sizeGb * 8192;
    const idealSec = totalMbits / speedMbps;
    const efficiency = Math.max(0.01, 1 - overhead / 100);
    const effectiveSpeedMbps = speedMbps * efficiency;
    const realSec = totalMbits / effectiveSpeedMbps;
    const rateMBps = effectiveSpeedMbps / 8;

    resRealTime.textContent = formatSeconds(realSec);
    resIdealTime.textContent = formatSeconds(idealSec);
    resTransferRate.textContent = rateMBps.toFixed(2) + ' MB/s';

    if (capGb > 0) {
      resCapCard.style.display = 'block';
      const usedPercent = Math.min(100, (sizeGb / capGb) * 100);
      const remaining = Math.max(0, capGb - sizeGb);
      resCapBar.style.width = usedPercent.toFixed(1) + '%';
      resCapUsed.textContent = 'Consumes ' + usedPercent.toFixed(1) + '% of monthly cap';
      resCapRemaining.textContent = remaining.toFixed(1) + ' GB remaining';
    } else {
      resCapCard.style.display = 'none';
    }
  }

  // Preset event listeners
  document.querySelectorAll('#dl-size-presets button').forEach((btn) => {
    btn.addEventListener('click', () => {
      sizeInput.value = btn.getAttribute('data-size');
      update();
    });
  });

  document.querySelectorAll('#dl-speed-presets button').forEach((btn) => {
    btn.addEventListener('click', () => {
      speedInput.value = btn.getAttribute('data-speed');
      update();
    });
  });

  document.querySelectorAll('#dl-cap-presets button').forEach((btn) => {
    btn.addEventListener('click', () => {
      capInput.value = btn.getAttribute('data-cap');
      update();
    });
  });

  [sizeInput, speedInput, overheadInput, capInput].forEach((input) => {
    input.addEventListener('input', update);
  });

  update();
})();
